var reports=new System.Collections.Generic.List<object>();foreach(var f in new[]{"WeatheredPanelFacade_01","WeatheredPanelFacade_Repairs3x3_01"}){string p="Assets/Maps/Buildings/Textures/"+f;var t=(UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath(p+"/WPF01_Normal_OpenGL.png");if(t.textureType!=UnityEditor.TextureImporterType.NormalMap)throw new Exception("Normal import "+f);reports.Add(new{folder=f,maps=System.IO.Directory.GetFiles(p,"*.png").Length,normal=t.textureType.ToString(),repeat=t.wrapMode.ToString()});}return reports;
